INSERT INTO `sectors` (`id`, `slug`, `name`, `summary`, `sort_order`) VALUES
(1, 'finance-administration', 'Finance and Administration', 'Books, payroll and consolidated records for the office that keeps the rest of the business accountable.', 10),
(2, 'education-utilities', 'Education and Utilities', 'Recurring accounts that are billed on a schedule: students by term, water consumers by reading cycle.', 20),
(3, 'retail-supply', 'Retail and Supply Chain', 'Selling floors and stock rooms, from the checkout counter back to the receiving dock.', 30),
(4, 'hospitality-food', 'Hospitality and Food Service', 'Rooms, tables and counters where the order has to reach the right person within minutes.', 40),
(5, 'services-recreation', 'Local Services and Recreation', 'Walk-in service businesses and bookable facilities that run on job tickets and time slots.', 50),
(6, 'logistics-construction', 'Logistics and Construction', 'Work that moves or gets built over days and months, tracked by status, cost and progress.', 60);
INSERT INTO `systems` (`id`, `sector_id`, `slug`, `name`, `category`, `tagline`, `summary`, `audience`, `manages`, `search_terms`, `implementation_notes`, `platforms`, `deployment`, `integrations`, `pricing`, `is_published`, `is_featured`, `sort_order`, `created_at`, `updated_at`) VALUES
(1, 1, 'accounting-finance', 'Accounting & Finance', 'Finance', 'One set of books that the whole office posts to and reports from.', 'Keeps the general ledger, receivables and payables in one place, so financial reports come from posted entries rather than separate spreadsheets.', 'Accounting staff, bookkeepers and business owners who need their ledgers, customer balances and supplier balances to agree with each other.', 'The chart of accounts, journal entries, sales invoices and collections, supplier bills and payments, and the financial statements that are drawn from them.', 'bookkeeping ledger invoices bills trial balance income statement balance sheet collections disbursements audit', 'Setup starts from your existing chart of accounts and opening balances.\nApproval steps and posting periods are agreed during configuration.\nReport layouts that your office already uses can be reviewed during the demo.', NULL, NULL, NULL, NULL, 1, 1, 10, '2026-01-01 08:00:00', '2026-01-01 08:00:00'),
(2, 1, 'human-resource-payroll', 'Human Resource & Payroll', 'Workforce', 'Attendance, leave and pay computed from the same employee record.', 'Holds employee records, attendance and leave, and computes each payroll run from them. Payslips and payroll registers come out of the same data.', 'HR officers and payroll staff in organizations where attendance, leave and pay are currently tracked in separate files.', 'Employee profiles and employment details, daily attendance, leave requests and balances, payroll periods, earnings and deductions, and payslips.', 'employees staff timekeeping dtr attendance leave payslip salary deductions overtime hris', 'Pay rules, deduction tables and cut-off dates are configured to your policies.\nAttendance can be encoded or imported from your time-recording source.\nStatutory computations should be reviewed with your accountant before the first live run.', NULL, NULL, NULL, NULL, 1, 1, 20, '2026-01-01 08:00:00', '2026-01-01 08:00:00'),
(3, 2, 'school-management', 'School Management', 'Education', 'Enrollment, classes and school fees kept on one student record.', 'Follows each student from enrollment through class assignment and fee payment. The registrar and the cashier work from the same record.', 'Registrars, cashiers and administrators of schools that enroll students by term and collect fees on a schedule.', 'Student information, enrollment by school year and term, sections and class schedules, fee assessments, payments and outstanding balances.', 'students enrollment registrar tuition fees sections subjects grades cashier assessment academic', 'Year levels, sections and fee schedules are set up before enrollment opens.\nExisting student lists can be brought in at the start so returning students are not re-encoded.\nReceipt numbering and layout are configured to the school''s practice.', NULL, NULL, NULL, NULL, 1, 0, 30, '2026-01-01 08:00:00', '2026-01-01 08:00:00'),
(4, 2, 'water-billing-collection', 'Water Billing & Collection', 'Utilities', 'From meter reading to collected payment, one account at a time.', 'Turns meter readings into bills for each billing cycle and records what consumers pay. Unpaid balances carry forward to the next bill.', 'Water service providers, cooperatives and associations that read meters, issue periodic bills and collect payments over the counter or in the field.', 'Consumer accounts and meters, reading routes, consumption per cycle, rate schedules, bills, payments, arrears and disconnection notices.', 'water utility consumers meters readings cubic consumption bills arrears collection cooperative waterworks', 'Rate schedules, minimum charges and penalties follow your approved tariff.\nExisting consumer accounts and their last readings are loaded before the first cycle.\nBill and receipt layouts are matched to the forms you already issue.', NULL, NULL, NULL, NULL, 1, 1, 40, '2026-01-01 08:00:00', '2026-01-01 08:00:00'),
(5, 3, 'retail-pos-inventory', 'Retail POS & Inventory', 'Retail', 'Every sale at the counter updates the stock behind it.', 'Runs the checkout counter and deducts stock with each sale. Purchases, price changes and sales reports draw on the same item list.', 'Store owners and staff of shops, groceries and supply stores that sell from a counter and restock from suppliers.', 'Items and prices, checkout transactions, stock on hand, purchases from suppliers, stock adjustments and sales reports by day, item and cashier.', 'store shop cashier checkout barcode receipt sales stock items purchases supplier grocery sari-sari', 'The item list can be loaded from an existing price list.\nReceipt format and any printer or scanner used at the counter are confirmed during setup.\nAn opening stock count is taken before the first selling day.', NULL, NULL, NULL, NULL, 1, 1, 50, '2026-01-01 08:00:00', '2026-01-01 08:00:00'),
(6, 3, 'ready-to-wear-business', 'Ready-to-Wear Business', 'Apparel Retail', 'Stock counted by size and color, not just by style.', 'Tracks clothing by style, size and color so staff can see which variants are in stock. Selling and customer orders deduct from the exact variant.', 'Clothing sellers, boutiques and online apparel shops whose stock is the same design in many sizes and colors.', 'Styles and their size and color variants, stock per variant, incoming stock, sales, customer orders and their fulfillment status.', 'clothing apparel boutique garments sizes colors variants rtw fashion orders online seller', 'Size and color sets are defined once and reused across styles.\nAn opening count by variant is needed before going live.\nOrder statuses are named to match how your shop already works.', NULL, NULL, NULL, NULL, 1, 0, 60, '2026-01-01 08:00:00', '2026-01-01 08:00:00'),
(7, 4, 'hotel-property-management', 'Hotel & Property Management', 'Hospitality', 'Front desk, housekeeping and guest charges on one room record.', 'Manages reservations, check-in and check-out, and the charges on each guest stay. Housekeeping sees which rooms need attention.', 'Front desk staff, housekeeping and managers of hotels, inns, resorts and transient houses.', 'Room types and rates, reservations, guest stays, room assignments, housekeeping status, charges posted to a stay and settlement at check-out.', 'hotel inn resort rooms reservations booking front desk check-in check-out guests housekeeping folio', 'Room types, room numbers and rates are set up first.\nChargeable items such as extra beds or services are listed during configuration.\nExisting future reservations are encoded before the switch-over date.', NULL, NULL, NULL, NULL, 1, 1, 70, '2026-01-01 08:00:00', '2026-01-01 08:00:00'),
(8, 4, 'restaurant-management', 'Restaurant Management', 'Food Service', 'Orders move from the table to the kitchen to the bill without re-writing.', 'Takes dine-in orders by table and sends them to the kitchen as tickets. The bill is built from what was served.', 'Dine-in restaurants where servers take orders at the table and the kitchen prepares them in sequence.', 'The menu, tables and their status, orders per table, kitchen tickets, bills, payments and sales reports by item and shift.', 'restaurant dine-in tables waiter server kitchen orders menu bill split eatery diner', 'The menu, categories and table layout are set up before opening.\nHow kitchen tickets are shown, on a screen or printed, is decided with you during setup.\nDiscount rules and service charges follow your current practice.', NULL, NULL, NULL, NULL, 1, 0, 80, '2026-01-01 08:00:00', '2026-01-01 08:00:00'),
(9, 4, 'coffee-shop-management', 'Coffee Shop Management', 'Food Service', 'Fast counter orders, with ingredients counted as drinks are sold.', 'Built for counter service: a menu with sizes and add-ons, quick order entry and delivery orders in the same queue. Ingredient stock is reduced as drinks are sold.', 'Cafes, milk tea shops and kiosks that take orders at the counter and prepare them while the customer waits.', 'Menu items with sizes and add-ons, counter and delivery orders, the preparation queue, ingredient inventory and daily transactions.', 'cafe coffee milk tea kiosk barista counter drinks add-ons delivery orders ingredients', 'Recipes are entered per menu item so ingredient use can be computed.\nDelivery orders are recorded by staff; any link to a delivery platform would be a separate integration to confirm.\nSizes and add-ons are defined once and applied across the menu.', NULL, NULL, NULL, NULL, 1, 0, 90, '2026-01-01 08:00:00', '2026-01-01 08:00:00'),
(10, 5, 'laundry-management', 'Laundry Management', 'Local Services', 'Every load tracked from the counter to the claim shelf.', 'Records each laundry order at intake and follows it through washing, drying and folding. Staff can tell a customer the status of their order and what is due.', 'Laundry shops and wash-dry-fold services that receive items from walk-in customers and release them later.', 'Customer orders, services and pricing by weight or item, order status at each stage, claim stubs, payments and unclaimed orders.', 'laundry laundromat wash dry fold dry cleaning kilos claim stub pickup', 'Service rates and add-ons are configured to your price list.\nHow customers are notified depends on the channels available to your shop and is confirmed during setup.\nClaim stub layout can follow the stub you currently issue.', NULL, NULL, NULL, NULL, 1, 0, 100, '2026-01-01 08:00:00', '2026-01-01 08:00:00'),
(11, 5, 'car-wash-management', 'Car Wash Management', 'Local Services', 'Know which vehicle is in which bay, and how long it has been there.', 'Logs each vehicle with its service package and assigns it to a bay. Job times, supplies used and collections are recorded per job.', 'Car wash and auto detailing shops that handle a queue of vehicles across several bays.', 'Service packages and prices, the vehicle queue, bay assignments, job start and finish times, supplies consumption and daily collections.', 'car wash carwash auto detailing vehicles bays queue washers wax vacuum', 'Packages, vehicle sizes and prices are set up from your current menu of services.\nThe number of bays and their names are configured to your site.\nIf crew incentives are computed per job, the basis is agreed during configuration.', NULL, NULL, NULL, NULL, 1, 0, 110, '2026-01-01 08:00:00', '2026-01-01 08:00:00'),
(12, 5, 'pickleball-court-booking', 'Pickleball Court Booking', 'Recreation', 'A clear schedule for every court, with fees tracked per booking.', 'Shows court availability by hour and records reservations against it. Fees and payments are tracked for each booking, so double bookings and unpaid slots are easy to spot.', 'Pickleball facilities and sports clubs that rent courts by the hour.', 'Courts and operating hours, hourly rates, reservations, occupancy through the day, booking fees and payment status.', 'pickleball courts sports facility reservation schedule slots rental club booking', 'Courts, operating hours and peak or off-peak rates are configured first.\nRules for deposits, cancellations and no-shows follow your facility policy.\nRecurring bookings for regular groups can be discussed during the demo.', NULL, NULL, NULL, NULL, 1, 0, 120, '2026-01-01 08:00:00', '2026-01-01 08:00:00'),
(13, 6, 'shipping-logistics', 'Shipping & Logistics', 'Logistics', 'One shipment record that everyone updates and anyone can check.', 'Keeps a record for each shipment with its sender, consignee and contents. Status is updated at each handover, so staff can answer where a shipment is.', 'Shipping lines, cargo forwarders and courier operators that accept shipments and move them between locations.', 'Shipment bookings, customers and consignees, cargo details, status updates along the route, charges and operational reports.', 'cargo freight forwarding courier waybill tracking shipments consignee delivery vessel trucking', 'Routes, locations and status names are configured to your operation.\nRate tables are loaded from your current tariff.\nWhether customers can look up status themselves is an option to confirm with GSMaRT.', NULL, NULL, NULL, NULL, 1, 0, 130, '2026-01-01 08:00:00', '2026-01-01 08:00:00'),
(14, 6, 'construction-management', 'Construction Management', 'Construction', 'Progress, materials and spending tracked against the project plan.', 'Organizes each project into tasks with a schedule and budget. Materials issued, expenses and accomplishment are recorded against it as work proceeds.', 'Contractors and project teams that run several projects and need to see progress and cost side by side.', 'Projects and their phases, tasks and schedules, materials requested and issued, expenses, labor and equipment assigned, and progress against plan.', 'contractor projects site engineer materials budget expenses progress accomplishment gantt building', 'Budget categories and task templates can follow your usual bill of quantities.\nOngoing projects are entered with their progress to date.\nApproval steps for material requests are agreed during configuration.', NULL, NULL, NULL, NULL, 1, 1, 140, '2026-01-01 08:00:00', '2026-01-01 08:00:00'),
(15, 1, 'multi-business-operations', 'Multi-Business Operations', 'Multi-Branch', 'Several businesses in one system, each with its own records.', 'Lets one owner or group run several businesses or branches in a single system. Each keeps its own data, and the owner can view them separately or together.', 'Owners and head offices that operate more than one company, branch or line of business.', 'Company and branch profiles, users and their access per business, separated transactions and records, and reports per business or consolidated.', 'branches companies group head office consolidated multi-company franchise outlets', 'Which operational modules run inside each business is decided per engagement.\nBusinesses can be added later without disturbing existing records.\nAccess rules are reviewed with you so sensitive figures stay with the right people.', NULL, NULL, NULL, NULL, 1, 0, 150, '2026-01-01 08:00:00', '2026-01-01 08:00:00'),
(16, 3, 'inventory-warehouse', 'Inventory & Warehouse', 'Supply Chain', 'What is in the warehouse, where it came from and when to reorder.', 'Records every receipt and issue of stock so quantities on hand can be trusted. Reorder levels flag items before they run out.', 'Warehouses, stock rooms and distributors that receive goods from suppliers and issue them to customers or branches.', 'Products and units, suppliers, receiving, issuances and transfers, stock on hand by location, stock counts and reorder levels.', 'warehouse stockroom stock card receiving issuance transfers suppliers reorder count distributor bodega', 'An opening count establishes starting quantities.\nLocations can be a single stock room or several warehouses.\nUnits of measure and conversions, such as box to piece, are set per product.', NULL, NULL, NULL, NULL, 1, 0, 160, '2026-01-01 08:00:00', '2026-01-01 08:00:00');
