INSERT INTO `system_workflow_steps` (`system_id`, `label`, `detail`, `sort_order`) VALUES
(1, 'Record the document', 'An invoice, bill, receipt or voucher is entered with its accounts and amounts.', 10),
(1, 'Review and post', 'An approver checks the entry before it is posted to the ledger.', 20),
(1, 'Collect or pay', 'Collections are applied to invoices and payments to bills, updating each balance.', 30),
(1, 'Reconcile', 'Cash and bank entries are matched against statements for the period.', 40),
(1, 'Close the period', 'The period is locked so posted figures no longer change.', 50),
(1, 'Report', 'Statements and schedules are produced from the posted entries.', 60),
(2, 'Maintain employee records', 'New hires and changes in position or pay are recorded as they happen.', 10),
(2, 'Capture attendance', 'Time records are collected for the pay period and exceptions are flagged.', 20),
(2, 'Approve leave and overtime', 'Supervisors act on pending requests before the cut-off.', 30),
(2, 'Run payroll', 'Earnings and deductions are computed for every employee in the period.', 40),
(2, 'Review and finalize', 'Payroll staff check the register, correct exceptions and lock the run.', 50),
(2, 'Release payslips', 'Payslips are issued and the run is kept for reference.', 60),
(3, 'Register the student', 'A new or returning student is recorded with their details and requirements.', 10),
(3, 'Enroll for the term', 'The student is placed in a year level and section for the school year.', 20),
(3, 'Assess fees', 'The fee schedule for that level produces the amount due.', 30),
(3, 'Collect payment', 'The cashier records payments and issues receipts.', 40),
(3, 'Produce class lists', 'Sections and schedules are finalized and class lists are released.', 50),
(3, 'Monitor balances', 'Unpaid balances are tracked through the term.', 60),
(4, 'Open the cycle', 'A billing period is opened with its reading and due dates.', 10),
(4, 'Enter readings', 'Present readings are recorded by route; unusual consumption is flagged for checking.', 20),
(4, 'Generate bills', 'Consumption is priced with the rate schedule and arrears are added.', 30),
(4, 'Distribute bills', 'Bills are printed or prepared for delivery by route.', 40),
(4, 'Collect payments', 'Tellers post payments and issue receipts.', 50),
(4, 'Follow up arrears', 'Accounts still unpaid after the due date are listed for notice.', 60),
(5, 'Set up items', 'Items are listed with their price, cost and opening quantity.', 10),
(5, 'Receive purchases', 'Deliveries from suppliers are added to stock.', 20),
(5, 'Sell at the counter', 'The cashier rings up items and takes payment.', 30),
(5, 'Close the shift', 'Cash is counted against the recorded sales for the shift.', 40),
(5, 'Review stock', 'Low or fast-moving items are checked for reordering.', 50),
(5, 'Read the reports', 'The owner reviews sales and margins for the period.', 60),
(6, 'Create the style', 'A design is listed with its available sizes and colors.', 10),
(6, 'Receive stock', 'Incoming pieces are counted in by variant.', 20),
(6, 'Sell or take an order', 'Staff pick the exact size and color being sold or reserved.', 30),
(6, 'Pack the order', 'Reserved pieces are pulled and packed.', 40),
(6, 'Release', 'The order is handed over or dispatched and marked complete.', 50),
(6, 'Review variants', 'Sold-out and slow-moving sizes and colors are reviewed for restocking.', 60),
(7, 'Take the reservation', 'Dates, room type and guest details are recorded.', 10),
(7, 'Assign a room', 'A specific room is allocated before or at arrival.', 20),
(7, 'Check in', 'The guest is registered and the stay begins.', 30),
(7, 'Post charges', 'Room nights and incidentals are added to the stay.', 40),
(7, 'Check out', 'The account is reviewed and settled.', 50),
(7, 'Turn the room', 'Housekeeping cleans the room and returns it to vacant.', 60),
(8, 'Seat the guests', 'A table is opened for the party.', 10),
(8, 'Take the order', 'Items are entered against the table.', 20),
(8, 'Send to the kitchen', 'A ticket is queued for preparation.', 30),
(8, 'Serve', 'Items are marked served as they leave the kitchen.', 40),
(8, 'Bill the table', 'The bill is produced and payment is taken.', 50),
(8, 'Clear the table', 'The table returns to free for the next party.', 60),
(9, 'Take the order', 'The cashier selects items, sizes and add-ons.', 10),
(9, 'Take payment', 'Payment is recorded and the order joins the queue.', 20),
(9, 'Prepare', 'The barista works through the queue.', 30),
(9, 'Hand over or dispatch', 'The order is called for pickup or passed to the rider.', 40),
(9, 'Count ingredients', 'Stock is reduced by what was used and low items are flagged.', 50),
(9, 'Close the day', 'Sales and cash are reviewed at closing.', 60),
(10, 'Receive items', 'Items are weighed or counted and the order is given a claim number.', 10),
(10, 'Assign services', 'Wash, dry, fold, press or other services are selected and priced.', 20),
(10, 'Track cleaning', 'The order moves through each stage as staff update it.', 30),
(10, 'Notify the customer', 'The order is marked ready so the customer can be informed.', 40),
(10, 'Release the order', 'Items are handed over against the claim number.', 50),
(10, 'Record payment', 'Any remaining balance is collected and the order is closed.', 60),
(11, 'Log the vehicle', 'Plate number, vehicle size and chosen package are recorded.', 10),
(11, 'Queue or assign a bay', 'The job waits in the queue or goes straight to a free bay.', 20),
(11, 'Start the job', 'The start time is recorded and the crew is noted.', 30),
(11, 'Finish and inspect', 'The job is marked done and the bay is freed.', 40),
(11, 'Collect payment', 'The customer pays for the package and add-ons.', 50),
(11, 'Review the day', 'Jobs, collections and supplies used are summarized.', 60),
(12, 'Check availability', 'Staff look up free slots for the requested date.', 10),
(12, 'Reserve the court', 'The slot is held under the player or group.', 20),
(12, 'Compute the fee', 'The rate for that time produces the amount due.', 30),
(12, 'Record payment', 'A deposit or full payment is posted to the booking.', 40),
(12, 'Check in the players', 'The booking is marked as played when the group arrives.', 50),
(12, 'Review occupancy', 'The manager reviews used and unused hours.', 60),
(13, 'Accept the shipment', 'Cargo details, shipper and consignee are recorded and a reference number is issued.', 10),
(13, 'Compute charges', 'Freight and other fees are assessed.', 20),
(13, 'Dispatch', 'The shipment is loaded and marked in transit.', 30),
(13, 'Update along the route', 'Each handover or arrival is recorded with its date.', 40),
(13, 'Deliver or release', 'The consignee receives the cargo and the release is recorded.', 50),
(13, 'Report', 'Volumes and pending shipments are reviewed.', 60),
(14, 'Set up the project', 'Scope, phases, budget and schedule are recorded.', 10),
(14, 'Plan the tasks', 'Work items are scheduled and assigned.', 20),
(14, 'Request and issue materials', 'Site requests are approved and materials are issued to the project.', 30),
(14, 'Record expenses', 'Costs are entered against budget categories.', 40),
(14, 'Report accomplishment', 'Site staff update the percentage complete for each task.', 50),
(14, 'Review progress and cost', 'Managers compare actual progress and spending with the plan.', 60),
(15, 'Register each business', 'Companies or branches are created with their own profile.', 10),
(15, 'Assign users', 'Staff are given access to the businesses they work in.', 20),
(15, 'Work within a business', 'Transactions are recorded under the selected business.', 30),
